# Round 508 Chinese-library score normalization: Chinese keywords alone must
# not let Madrid/Valencia/other Spain records outrank Barcelona-local cards.
# Keep the records and their evidence, but make location priority visible in
# the numeric score used by both the data order and the browser sort.
foreach ($mergedRecord in $records) {
  $sourceText = (@($mergedRecord.source, $mergedRecord.contact, $mergedRecord.searchText) -join ' ')
  $isChineseSource = ([string]$mergedRecord.sourceGroup -eq 'chinese') -or ($sourceText -match '(?i)xihua|huarenjie|infohuaxin|eulam|es02|bbs\.eus|casa asia|华人|中文|西华|华信|欧浪')
  if (-not $isChineseSource) { continue }

  $locationText = [string]$mergedRecord.location
  $scoreDelta = 0
  $hasStableRound508Normalization = [string]$mergedRecord.analysis -match 'Round 508 location priority v2'
  $hasLegacyRound508Normalization = ([string]$mergedRecord.analysis -match 'Round 508 location priority') -and (-not $hasStableRound508Normalization)
  if ($locationText -match '(?i)Madrid|Getafe|Fuenlabrada|Humanes|Cobo Calleja|Valencia|Pinto|Parla|Alcobendas') {
    $scoreDelta = -22
  } elseif (($locationText -match '(?i)Spain remote|remote|远程') -and ($locationText -notmatch '(?i)Barcelona|Badalona|Hospitalet|Cornell|Sant Cugat')) {
    $scoreDelta = -10
  }

  if ($scoreDelta -ne 0) {
    # ExistingDataPath is fed back into the generator on every run. Migrate
    # the first implementation's marker once, then leave stable v2 records
    # untouched so scores do not drift on future wake-ups.
    if ($hasStableRound508Normalization) {
      continue
    }
    if ($hasLegacyRound508Normalization) {
      $mergedRecord.score = [math]::Max(0, ([int]$mergedRecord.score + $scoreDelta))
      $mergedRecord.analysis = ([string]$mergedRecord.analysis -replace 'Round 508 location priority: Chinese-source records outside Barcelona are kept below Barcelona-local cards until local relevance is confirmed\.', 'Round 508 location priority v2: Chinese-source records outside Barcelona are kept below Barcelona-local cards until local relevance is confirmed.')
      $combinedForTier = (@($mergedRecord.source, $mergedRecord.opportunity, $mergedRecord.fit, $mergedRecord.location, $mergedRecord.status, $mergedRecord.contact, $mergedRecord.analysis, $mergedRecord.searchText) -join ' ')
      $mergedRecord.tier = Get-Tier ([int]$mergedRecord.score) $combinedForTier
      continue
    }
    $newScore = [math]::Max(0, ([int]$mergedRecord.score + $scoreDelta))
    $mergedRecord.score = [int]$newScore
    $combinedForTier = (@($mergedRecord.source, $mergedRecord.opportunity, $mergedRecord.fit, $mergedRecord.location, $mergedRecord.status, $mergedRecord.contact, $mergedRecord.analysis, $mergedRecord.searchText) -join ' ')
    $mergedRecord.tier = Get-Tier ([int]$newScore) $combinedForTier
    if ([string]$mergedRecord.analysis -notmatch 'Round 508 location priority') {
      $mergedRecord.analysis = (([string]$mergedRecord.analysis).TrimEnd() + ' Round 508 location priority v2: Chinese-source records outside Barcelona are kept below Barcelona-local cards until local relevance is confirmed.')
    }
  }
}

