# Older generator revisions appended audit/injection copies after the normal
# merge stage.  From ID 921000 onward those were mechanically allocated IDs,
# not bookmarked public IDs.  Collapse only those late generated copies when
# an earlier record already owns the exact, vacancy-specific route.  Generic
# careers pages deliberately have no `route:` key, so distinct vacancies on a
# shared careers hub remain separate; all historical evidence on the retained
# canonical card remains intact.
# Keep this final guard deliberately lightweight. The structured `links` field
# is sufficient here; parsing every long contact/status text again made an
# otherwise idempotent regeneration exceed the command timeout.
function Get-ListedVacancyRouteKeys {
  param([object]$Record)
  $keys = New-Object 'System.Collections.Generic.List[string]'
  foreach ($link in @($Record.links)) {
    $value = ([string]$link).Trim()
    if ($value -notmatch '^https?://') { continue }
    $normal = ($value -replace '#.*$', '').TrimEnd('/').ToLowerInvariant()
    $baseUrl = ($normal -replace '\?.*$', '')
    $pathPart = ($baseUrl -replace '^https?://[^/]+', '')
    $queryPart = ''
    if ($normal -match '\?(?<query>.*)$') { $queryPart = $Matches['query'] }
    $vacancyPairs = @([regex]::Matches($queryPart, '(?i)(?:^|&)(?:tid|id|job|jobid|job_id|jk|gh_jid|requisition|req|posting|listing)=[^&]+') | ForEach-Object { $_.Value.TrimStart('&') } | Sort-Object -Unique)
    $hasVacancyQuery = $vacancyPairs.Count -gt 0
    # Discard UI pagination, search-position and tracking parameters.  A
    # LinkedIn URL with `pageNum` must canonicalise to the same vacancy as the
    # clean employer URL; actual identifiers such as `tid` and `job` stay.
    $routeKey = $baseUrl
    if ($hasVacancyQuery) { $routeKey += ('?' + ($vacancyPairs -join '&')) }
    if ($pathPart -match '(?i)(?:/jobs?/|/job_posting/|/job-boards?/|/listing/|/positions?/|/offer(?:s)?/|/empleo/|/trabajo/|/vacan(?:te|cy)|/o/|/apply/|/career/[^/]+/[^/]+|\.pdf$)' -or $pathPart -match '\d{5,}' -or $hasVacancyQuery) {
      $keys.Add(('route:' + $routeKey))
    }
  }
  return @($keys | Select-Object -Unique)
}

$lateGeneratedFloor = 921000
$seenVacancyRoutes = New-Object 'System.Collections.Generic.HashSet[string]'
$seenLateLabels = New-Object 'System.Collections.Generic.HashSet[string]'
$routeCanonicalRecords = New-Object 'System.Collections.Generic.List[object]'
foreach ($candidate in @($records | Sort-Object @{Expression={ [int]$_.id }; Descending=$false})) {
  $candidateId = [int]$candidate.id
  $candidateRoutes = @(Get-ListedVacancyRouteKeys $candidate)
  $candidateLabel = 'label:' + (Get-RecordIdentity $candidate)
  $hasRouteDuplicate = $candidateRoutes.Count -gt 0 -and @($candidateRoutes | Where-Object { $seenVacancyRoutes.Contains($_) }).Count -gt 0
  # Generic careers/research routes have no job-specific URL. For the late
  # auto-generated range, fall back to the stable source/title identity so the
  # same audit card cannot be appended once per regeneration.
  $hasLateLabelDuplicate = $seenLateLabels.Contains($candidateLabel)
  $isLateDuplicate = $candidateId -ge $lateGeneratedFloor -and ($hasRouteDuplicate -or $hasLateLabelDuplicate)
  if ($isLateDuplicate) { continue }
  foreach ($route in $candidateRoutes) { [void]$seenVacancyRoutes.Add($route) }
  [void]$seenLateLabels.Add($candidateLabel)
  [void]$routeCanonicalRecords.Add($candidate)
}
$records = @($routeCanonicalRecords.ToArray())

