# Use explicit numeric scriptblocks instead of a property-name sort so the
# generated data order itself is score-descending, not only the browser view.
$sorted = @($records | Sort-Object `
  @{Expression={ $value = $_.score; if ($null -eq $value) { $value = $_['score'] }; if ($null -eq $value) { 0 } else { [int]$value } }; Descending=$true}, `
  @{Expression={ $value = $_.id; if ($null -eq $value) { $value = $_['id'] }; if ($null -eq $value) { 0 } else { [int]$value } }; Descending=$false})
$payload = [ordered]@{
  generatedAt = (Get-Date).ToString('yyyy-MM-dd HH:mm:ss')
  tracker = [string]$tracker
  total = @($sorted).Count
}

$jsonMeta = $payload | ConvertTo-Json -Depth 5 -Compress
$jsonData = @($sorted) | ConvertTo-Json -Depth 12 -Compress
$content = "window.JOB_META = $jsonMeta;`nwindow.JOB_OPPORTUNITIES = $jsonData;`n"
$utf8 = [System.Text.UTF8Encoding]::new($false)
[System.IO.File]::WriteAllText($out, $content, $utf8)
Write-Output "Generated $(@($sorted).Count) records -> $out"
